import type { AdRunnerManifest, CandidateOutcome, CandidateResult, Placement, PlacementCandidate } from "../specification/types.js"; import { getAdapter, type RuntimeContext } from "../adapters/index.js";
export interface RouteResult { placement:string; filled:boolean; selectedPartner?:string; finalPartner?:string; finalUnit?:string; outcome?:string; attempts:Array<{unit:string; outcome:CandidateOutcome; reason?:string; elapsedMs:number}>; }
export class PlacementRouter { constructor(private manifest:AdRunnerManifest, private emit:(name:string,detail:Record<string,unknown>)=>void){} async route(placement:Placement,target:Element,context:RuntimeContext & {selection?:any, reportOutcome?:(body:any)=>Promise<void>}):Promise<RouteResult>{ const attempts:RouteResult["attempts"]=[]; target.textContent=""; this.emit("slot-requested",{placement:placement.id,anchor:placement.anchor}); const selectedPartner=context.selection?.partner; const selected=placement.partners?.find(p=>p.partner_id===selectedPartner); let lanes:{partner_id:string; lane:PlacementCandidate[]}[]=[]; if(selected) lanes.push({partner_id:selected.partner_id,lane:context.selection.lane??selected.lane}); else if(placement.partners?.length) lanes=[{partner_id:manifestWeighted(placement), lane:placement.partners.find(p=>p.partner_id===manifestWeighted(placement))!.lane}]; else lanes=[{partner_id:"legacy",lane:placement.candidates}];
    if(placement.share_policy==="open-yield"&&placement.partners) for(const p of placement.partners) if(p.partner_id!==lanes[0].partner_id) lanes.push({partner_id:p.partner_id,lane:p.lane});
    let finalPartner="", finalUnit="", outcome="collapsed";
    for(const lane of lanes){ const res=await this.tryLane(placement,lane.lane,target,context,attempts,lane.partner_id); if(res){ finalPartner=lane.partner_id; finalUnit=res; outcome=lane.partner_id===selectedPartner||!selectedPartner?"filled":"recovery-fill"; await context.reportOutcome?.({cycle_id:context.selection?.cycle_id,selected_partner:selectedPartner,final_partner:finalPartner,unit:finalUnit,outcome}); return {placement:placement.id,filled:true,selectedPartner,finalPartner,finalUnit,outcome,attempts}; } if(placement.share_policy==="protected-share") break; }
    if(placement.neutral_fallback){ const res=await this.tryLane(placement,[{unit:placement.neutral_fallback,priority:0,timeout_ms:1500,guaranteed:true}],target,context,attempts,""); if(res){ outcome="neutral-fallback"; await context.reportOutcome?.({cycle_id:context.selection?.cycle_id,selected_partner:selectedPartner,unit:res,outcome}); return {placement:placement.id,filled:true,selectedPartner,finalUnit:res,outcome,attempts}; }}
    this.emit("slot-collapsed",{placement:placement.id,anchor:placement.anchor}); target.textContent=""; await context.reportOutcome?.({cycle_id:context.selection?.cycle_id,selected_partner:selectedPartner,outcome:"collapsed"}); return {placement:placement.id,filled:false,selectedPartner,outcome:"collapsed",attempts}; }
  private async tryLane(placement:Placement,candidates:PlacementCandidate[],target:Element,context:RuntimeContext,attempts:RouteResult["attempts"],partner:string){ for(const [i,c] of candidates.entries()){ const devices=c.devices??this.manifest.units[c.unit]?.devices??["all"]; const mobile=window.innerWidth<=767; if(!devices.includes("all")&&!devices.includes(mobile?"mobile":"desktop")) continue; const unit=this.manifest.units[c.unit]; const network=unit&&this.manifest.networks[unit.network]; if(!unit||!network?.enabled) continue; const adapter=getAdapter(network.adapter); const container=document.createElement("div"); container.dataset.adRunnerCandidate=c.unit; target.appendChild(container); const started=performance.now(); this.emit("candidate-started",{placement:placement.id,anchor:placement.anchor,unit:c.unit,network:unit.network,partner,candidateIndex:i}); const controller=new AbortController(); let timer:number|undefined; try{ if(adapter.load) await adapter.load(network,context); const result=await Promise.race<CandidateResult>([adapter.mount(unit,container,context,controller.signal),new Promise(r=>{timer=window.setTimeout(()=>r({outcome:"timeout",reason:"candidate timeout"} as CandidateResult),c.timeout_ms);})]); const elapsedMs=Math.round(performance.now()-started); attempts.push({unit:c.unit,outcome:result.outcome,reason:result.reason,elapsedMs}); this.emit(`candidate-${result.outcome}`,{placement:placement.id,anchor:placement.anchor,unit:c.unit,network:unit.network,partner,candidateIndex:i,outcome:result.outcome,elapsedMs}); if(result.outcome==="filled"){ target.querySelectorAll(":scope > [data-ad-runner-candidate]").forEach(el=>{if(el!==container) el.remove();}); this.emit("slot-filled",{placement:placement.id,anchor:placement.anchor,unit:c.unit,network:unit.network,partner,outcome:"filled",elapsedMs}); return c.unit; } controller.abort(); await adapter.destroy?.(unit,container,context); container.remove(); } catch(e){ const elapsedMs=Math.round(performance.now()-started); attempts.push({unit:c.unit,outcome:"error",reason:String((e as Error).message),elapsedMs}); this.emit("candidate-error",{placement:placement.id,unit:c.unit,network:unit.network,partner,candidateIndex:i,outcome:"error",elapsedMs}); controller.abort(); await adapter.destroy?.(unit,container,context).catch(()=>{}); container.remove(); } finally{ if(timer) clearTimeout(timer); } } return ""; }}
function manifestWeighted(p:Placement){ const partners=p.partners??[]; const total=partners.reduce((s,x)=>s+x.share_target,0)||1; const key=Date.now()%total; let n=0; for(const x of [...partners].sort((a,b)=>a.partner_id.localeCompare(b.partner_id))){ n+=x.share_target; if(key<n) return x.partner_id; } return partners[0]?.partner_id??"legacy"; }
